        "content": "/**\n * DISPOSABLE - Additional edge case tests for HYP-001.\n * Focus: tricky valid patterns that might produce false positives,\n * and tricky invalid patterns.\n */\n\nimport { validateYaml } from \"./yaml-validator\";\n\ninterface TestCase {\n  id: string;\n  name: string;\n  input: string;\n  expectedValid: boolean;\n  expectedLine?: number;\n  description: string;\n}\n\nconst edgeCases: TestCase[] = [\n  // Tricky VALID cases\n  {\n    id: \"E01\",\n    name: \"Colon in unquoted URL value\",\n    input: \"website: http://example.com:8080/path\\n\",\n    expectedValid: true,\n    description: \"URL with port -- colon is part of value, not mapping indicator\",\n  },\n  {\n    id: \"E02\",\n    name: \"Hash in quoted string (not a comment)\",\n    input: 'color: \"#ff0000\"\\n',\n    expectedValid: true,\n    description: \"Hash inside double quotes should not be treated as comment\",\n  },\n  {\n    id: \"E03\",\n    name: \"Braces in quoted string\",\n    input: 'template: \"{name} is {age} years old\"\\n',\n    expectedValid: true,\n    description: \"Curly braces inside quoted string should not affect flow tracking\",\n  },\n  {\n    id: \"E04\",\n    name: \"Brackets in quoted string\",\n    input: \"regex: '[a-z]+'\\n\",\n    expectedValid: true,\n    description: \"Square brackets inside quoted string should not affect flow tracking\",\n  },\n  {\n    id: \"E05\",\n    name: \"Multiple documents\",\n    input: `---\nname: Alice\n---\nname: Bob\n...\n`,\n    expectedValid: true,\n    description: \"Multiple YAML documents separated by ---\",\n  },\n  {\n    id: \"E06\",\n    name: \"Anchor and alias\",\n    input: `defaults: &defaults\n  timeout: 30\n  retries: 3\nproduction:\n  <<: *defaults\n  timeout: 60\n`,\n    expectedValid: true,\n    description: \"YAML anchors and aliases (syntax-level valid)\",\n  },\n  {\n    id: \"E07\",\n    name: \"Complex nested with flow and block\",\n    input: `servers:\n  - name: web\n    ports: [80, 443]\n    config:\n      ssl: true\n      headers: {X-Frame-Options: DENY}\n`,\n    expectedValid: true,\n    description: \"Mix of block and flow styles in nested structure\",\n  },\n  {\n    id: \"E08\",\n    name: \"Empty mapping value\",\n    input: `key:\nother: value\n`,\n    expectedValid: true,\n    description: \"Mapping key with empty value (followed by newline)\",\n  },\n  {\n    id: \"E09\",\n    name: \"Sequence item with flow mapping\",\n    input: `- {name: Alice, age: 30}\n- {name: Bob, age: 25}\n`,\n    expectedValid: true,\n    description: \"Root sequence of flow mappings\",\n  },\n  {\n    id: \"E10\",\n    name: \"Quoted key\",\n    input: `\"special key\": value\n'another key': value2\n`,\n    expectedValid: true,\n    description: \"Mapping keys that are quoted strings\",\n  },\n  {\n    id: \"E11\",\n    name: \"Multiline flow mapping\",\n    input: `config: {\n  name: Alice,\n  age: 30,\n  active: true\n}\n`,\n    expectedValid: true,\n    description: \"Flow mapping spread across multiple lines\",\n  },\n  {\n    id: \"E12\",\n    name: \"Block scalar followed by more content\",\n    input: `description: |\n  Line one\n  Line two\nnext_key: value\n`,\n    expectedValid: true,\n    description: \"Block scalar terminated by de-indented key\",\n  },\n  {\n    id: \"E13\",\n    name: \"Empty sequence items\",\n    input: `-\n-\n- value\n`,\n    expectedValid: true,\n    description: \"Sequence with empty items\",\n  },\n  {\n    id: \"E14\",\n    name: \"Unicode content\",\n    input: `greeting: \"Hello, World!\"\njapanese: \"Konichiwa\"\nemoji_text: \"test value\"\n`,\n    expectedValid: true,\n    description: \"Unicode characters in values\",\n  },\n  {\n    id: \"E15\",\n    name: \"Very long line\",\n    input: `long_value: ${\"a\".repeat(10000)}\\n`,\n    expectedValid: true,\n    description: \"Line with 10000 characters\",\n  },\n\n  // Tricky INVALID cases\n  {\n    id: \"E16\",\n    name: \"Tab in middle of indentation\",\n    input: \"root:\\n   \\tchild: value\\n\",\n    expectedValid: false,\n    expectedLine: 2,\n    description: \"Three spaces then a tab -- still tab indentation\",\n  },\n  {\n    id: \"E17\",\n    name: \"Unclosed quote after nested content\",\n    input: `items:\n  - name: \"Alice\n  - name: Bob\n`,\n    expectedValid: false,\n    expectedLine: 2,\n    description: \"Unclosed double quote in sequence item value\",\n  },\n  {\n    id: \"E18\",\n    name: \"Invalid block scalar with letters\",\n    input: `data: |abc\n  content here\n`,\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Block scalar header with non-numeric, non-chomping characters\",\n  },\n];\n\nlet totalTests = 0;\nlet passed = 0;\nlet failed = 0;\nconst failures: string[] = [];\n\nfunction runTest(tc: TestCase) {\n  totalTests++;\n  const result = validateYaml(tc.input);\n\n  if (tc.expectedValid) {\n    if (result.valid) {\n      passed++;\n      console.log(`  PASS ${tc.id}: ${tc.name}`);\n    } else {\n      failed++;\n      const err = result as { valid: false; line: number; message: string };\n      const detail = `Expected VALID but got error at line ${err.line}: \"${err.message}\"`;\n      failures.push(`${tc.id} (${tc.name}): ${detail}`);\n      console.log(`  FAIL ${tc.id}: ${tc.name} -- ${detail}`);\n    }\n  } else {\n    if (!result.valid) {\n      const err = result as { valid: false; line: number; message: string };\n      if (tc.expectedLine !== undefined && err.line !== tc.expectedLine) {\n        failed++;\n        const detail = `Error detected but wrong line: expected ${tc.expectedLine}, got ${err.line} (\"${err.message}\")`;\n        failures.push(`${tc.id} (${tc.name}): ${detail}`);\n        console.log(`  FAIL ${tc.id}: ${tc.name} -- ${detail}`);\n      } else {\n        passed++;\n        console.log(\n          `  PASS ${tc.id}: ${tc.name} -- error at line ${err.line}: \"${err.message}\"`\n        );\n      }\n    } else {\n      failed++;\n      const detail = `Expected INVALID but got valid`;\n      failures.push(`${tc.id} (${tc.name}): ${detail}`);\n      console.log(`  FAIL ${tc.id}: ${tc.name} -- ${detail}`);\n    }\n  }\n}\n\nconsole.log(\"=== EDGE CASE TESTS ===\");\nconsole.log(`Testing ${edgeCases.length} edge cases:\\n`);\nfor (const tc of edgeCases) {\n  runTest(tc);\n}\n\nconsole.log(\"\\n=== EDGE CASE SUMMARY ===\");\nconsole.log(`Total tests: ${totalTests}`);\nconsole.log(`Passed: ${passed}`);\nconsole.log(`Failed: ${failed}`);\n\nif (failures.length > 0) {\n  console.log(\"\\n=== FAILURES ===\");\n  for (const f of failures) {\n    console.log(`  - ${f}`);\n  }\n}\n\nconsole.log(`\\n=== RESULT: ${failed === 0 ? \"ALL PASSED\" : \"SOME FAILED\"} ===`);\n"
