        "content": "/**\n * DISPOSABLE test harness for HYP-001 validation.\n * Tests a from-scratch YAML syntax checker against valid and invalid patterns.\n */\n\nimport { validateYaml } from \"./yaml-validator\";\n\ninterface TestCase {\n  id: string;\n  name: string;\n  input: string;\n  expectedValid: boolean;\n  expectedLine?: number; // For invalid cases: expected error line\n  description: string;\n}\n\n// ============================================================================\n// VALID YAML PATTERNS (15+ cases)\n// ============================================================================\n\nconst validCases: TestCase[] = [\n  {\n    id: \"V01\",\n    name: \"Empty file\",\n    input: \"\",\n    expectedValid: true,\n    description: \"Empty content is valid YAML per spec\",\n  },\n  {\n    id: \"V02\",\n    name: \"Simple key-value\",\n    input: \"name: Alice\\nage: 30\\n\",\n    expectedValid: true,\n    description: \"Basic mapping with string and numeric values\",\n  },\n  {\n    id: \"V03\",\n    name: \"Nested mappings\",\n    input: `database:\n  host: localhost\n  port: 5432\n  credentials:\n    username: admin\n    password: secret\n`,\n    expectedValid: true,\n    description: \"Multi-level nested mappings with consistent indentation\",\n  },\n  {\n    id: \"V04\",\n    name: \"Sequences (lists)\",\n    input: `fruits:\n  - apple\n  - banana\n  - cherry\n`,\n    expectedValid: true,\n    description: \"Mapping with a sequence value\",\n  },\n  {\n    id: \"V05\",\n    name: \"Block scalar (literal |)\",\n    input: `description: |\n  This is a multi-line\n  block scalar that preserves\n  newlines exactly.\n`,\n    expectedValid: true,\n    description: \"Literal block scalar with pipe indicator\",\n  },\n  {\n    id: \"V06\",\n    name: \"Block scalar (folded >)\",\n    input: `summary: >\n  This is a folded\n  block scalar that folds\n  newlines into spaces.\n`,\n    expectedValid: true,\n    description: \"Folded block scalar with greater-than indicator\",\n  },\n  {\n    id: \"V07\",\n    name: \"Flow mapping\",\n    input: `person: {name: Alice, age: 30}\n`,\n    expectedValid: true,\n    description: \"Inline flow mapping with curly braces\",\n  },\n  {\n    id: \"V08\",\n    name: \"Flow sequence\",\n    input: `colors: [red, green, blue]\n`,\n    expectedValid: true,\n    description: \"Inline flow sequence with square brackets\",\n  },\n  {\n    id: \"V09\",\n    name: \"Comments\",\n    input: `# This is a comment\nname: Alice # inline comment\n# Another comment\nage: 30\n`,\n    expectedValid: true,\n    description: \"Full-line and inline comments\",\n  },\n  {\n    id: \"V10\",\n    name: \"Double-quoted strings\",\n    input: `greeting: \"Hello, World!\"\npath: \"C:\\\\Users\\\\admin\"\nmessage: \"Line with \\\\\"escaped\\\\\" quotes\"\n`,\n    expectedValid: true,\n    description: \"Double-quoted strings with special characters\",\n  },\n  {\n    id: \"V11\",\n    name: \"Single-quoted strings\",\n    input: `greeting: 'Hello, World!'\nnote: 'It''s a nice day'\n`,\n    expectedValid: true,\n    description: \"Single-quoted strings with escaped apostrophe\",\n  },\n  {\n    id: \"V12\",\n    name: \"Document markers\",\n    input: `---\nname: Alice\nage: 30\n...\n`,\n    expectedValid: true,\n    description: \"Document start (---) and end (...) markers\",\n  },\n  {\n    id: \"V13\",\n    name: \"Mixed content (mappings + sequences)\",\n    input: `servers:\n  - name: web1\n    port: 8080\n    tags:\n      - production\n      - frontend\n  - name: web2\n    port: 8081\n    tags:\n      - staging\n`,\n    expectedValid: true,\n    description: \"Complex nested structure with mappings and sequences mixed\",\n  },\n  {\n    id: \"V14\",\n    name: \"Boolean and null values\",\n    input: `enabled: true\ndisabled: false\nvalue: null\nnothing: ~\n`,\n    expectedValid: true,\n    description: \"YAML boolean and null literal values\",\n  },\n  {\n    id: \"V15\",\n    name: \"Only whitespace\",\n    input: `\n\n`,\n    expectedValid: true,\n    description: \"File with only whitespace lines is valid\",\n  },\n  {\n    id: \"V16\",\n    name: \"Only comments\",\n    input: `# This file has\n# only comments\n# and nothing else\n`,\n    expectedValid: true,\n    description: \"File with only comment lines is valid\",\n  },\n  {\n    id: \"V17\",\n    name: \"Block scalar with chomping indicator\",\n    input: `text: |+\n  Keep trailing newlines\n  in this block.\n\nanother: >-\n  Strip trailing newlines\n  from this folded block.\n`,\n    expectedValid: true,\n    description: \"Block scalars with + (keep) and - (strip) chomping\",\n  },\n  {\n    id: \"V18\",\n    name: \"Block scalar with indentation indicator\",\n    input: `text: |2\n    This is indented by 2 extra\n    spaces relative to the indicator.\n`,\n    expectedValid: true,\n    description: \"Block scalar with explicit indentation indicator\",\n  },\n  {\n    id: \"V19\",\n    name: \"Nested flow collections\",\n    input: `matrix: [[1, 2], [3, 4]]\nconfig: {a: {b: {c: 1}}}\n`,\n    expectedValid: true,\n    description: \"Deeply nested flow sequences and mappings\",\n  },\n  {\n    id: \"V20\",\n    name: \"Multiline flow collection\",\n    input: `items: [\n  apple,\n  banana,\n  cherry\n]\n`,\n    expectedValid: true,\n    description: \"Flow sequence spread across multiple lines\",\n  },\n  {\n    id: \"V21\",\n    name: \"Colon in values\",\n    input: `url: http://example.com\ntime: \"10:30\"\nnote: 'key: value'\n`,\n    expectedValid: true,\n    description: \"Colons inside values (URL, quoted strings)\",\n  },\n  {\n    id: \"V22\",\n    name: \"Document end marker only\",\n    input: `...\n`,\n    expectedValid: true,\n    description: \"Just a document end marker\",\n  },\n  {\n    id: \"V23\",\n    name: \"Sequence of mappings at root\",\n    input: `- name: Alice\n  age: 30\n- name: Bob\n  age: 25\n`,\n    expectedValid: true,\n    description: \"Root-level sequence of mappings\",\n  },\n];\n\n// ============================================================================\n// INVALID YAML PATTERNS (8+ cases)\n// ============================================================================\n\nconst invalidCases: TestCase[] = [\n  {\n    id: \"I01\",\n    name: \"Tab indentation\",\n    input: \"name: Alice\\n\\tage: 30\\n\",\n    expectedValid: false,\n    expectedLine: 2,\n    description: \"Tab used for indentation on line 2\",\n  },\n  {\n    id: \"I02\",\n    name: \"Unclosed double quote\",\n    input: 'name: \"Alice\\nage: 30\\n',\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Double quote opened but not closed on line 1\",\n  },\n  {\n    id: \"I03\",\n    name: \"Unclosed single quote\",\n    input: \"name: 'Alice\\nage: 30\\n\",\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Single quote opened but not closed on line 1\",\n  },\n  {\n    id: \"I04\",\n    name: \"Unbalanced opening brace\",\n    input: \"config: {name: Alice\\nage: 30\\n\",\n    expectedValid: false,\n    // Error should appear at end of file (unmatched flow)\n    description: \"Opening brace without closing brace\",\n  },\n  {\n    id: \"I05\",\n    name: \"Unbalanced opening bracket\",\n    input: \"items: [apple, banana\\nother: value\\n\",\n    expectedValid: false,\n    description: \"Opening bracket without closing bracket\",\n  },\n  {\n    id: \"I06\",\n    name: \"Unbalanced closing brace\",\n    input: \"name: Alice}\\nage: 30\\n\",\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Closing brace without opening brace\",\n  },\n  {\n    id: \"I07\",\n    name: \"Unbalanced closing bracket\",\n    input: \"name: Alice]\\nage: 30\\n\",\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Closing bracket without opening bracket\",\n  },\n  {\n    id: \"I08\",\n    name: \"Invalid block scalar header\",\n    input: \"text: |invalid\\n  some content\\n\",\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Block scalar with invalid modifier characters\",\n  },\n  {\n    id: \"I09\",\n    name: \"Tab indentation on first line\",\n    input: \"\\tname: Alice\\n\",\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Tab at the very start of the file\",\n  },\n  {\n    id: \"I10\",\n    name: \"Mixed space-tab indentation\",\n    input: \"parent:\\n  \\tchild: value\\n\",\n    expectedValid: false,\n    expectedLine: 2,\n    description: \"Spaces followed by tab for indentation\",\n  },\n  {\n    id: \"I11\",\n    name: \"Invalid block scalar header (folded)\",\n    input: \"summary: >abc\\n  some content\\n\",\n    expectedValid: false,\n    expectedLine: 1,\n    description: \"Folded block scalar with invalid modifier\",\n  },\n];\n\n// ============================================================================\n// TEST RUNNER\n// ============================================================================\n\nlet totalTests = 0;\nlet passed = 0;\nlet failed = 0;\nconst failures: string[] = [];\n\nfunction runTest(tc: TestCase) {\n  totalTests++;\n  const result = validateYaml(tc.input);\n\n  if (tc.expectedValid) {\n    if (result.valid) {\n      passed++;\n      console.log(`  PASS ${tc.id}: ${tc.name}`);\n    } else {\n      failed++;\n      const err = result as { valid: false; line: number; message: string };\n      const detail = `Expected VALID but got error at line ${err.line}: \"${err.message}\"`;\n      failures.push(`${tc.id} (${tc.name}): ${detail}`);\n      console.log(`  FAIL ${tc.id}: ${tc.name} -- ${detail}`);\n    }\n  } else {\n    if (!result.valid) {\n      const err = result as { valid: false; line: number; message: string };\n      // Check line number if expected\n      if (tc.expectedLine !== undefined && err.line !== tc.expectedLine) {\n        failed++;\n        const detail = `Error detected but wrong line: expected ${tc.expectedLine}, got ${err.line} (\"${err.message}\")`;\n        fail