e-version: \\${{ matrix.node-version }}\n      - run: npm ci\n      - run: npm test\n\n  deploy:\n    needs: test\n    if: github.ref == 'refs/heads/main'\n    runs-on: ubuntu-latest\n    environment:\n      name: production\n      url: https://example.com\n    steps:\n      - uses: actions/checkout@v4\n      - name: Deploy\n        run: |\n          echo \"Deploying to production...\"\n          npm run build\n          npm run deploy\n        env:\n          API_KEY: \\${{ secrets.API_KEY }}\n`;\n\n// Docker Compose-style config\nconst dockerCompose = `version: \"3.8\"\nservices:\n  web:\n    build:\n      context: .\n      dockerfile: Dockerfile\n      args:\n        NODE_ENV: production\n    ports:\n      - \"8080:8080\"\n      - \"8443:8443\"\n    environment:\n      - DATABASE_URL=postgres://postgres:password@db:5432/myapp\n      - REDIS_URL=redis://cache:6379\n    depends_on:\n      - db\n      - cache\n    networks:\n      - frontend\n      - backend\n    deploy:\n      replicas: 3\n      resources:\n        limits:\n          cpus: '0.50'\n          memory: 512M\n  db:\n    image: postgres:16\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n    environment:\n      POSTGRES_DB: myapp\n      POSTGRES_USER: postgres\n      POSTGRES_PASSWORD: password\n  cache:\n    image: redis:7-alpine\n    command: redis-server --maxmemory 256mb\n\nvolumes:\n  postgres_data:\n\nnetworks:\n  frontend:\n  backend:\n`;\n\n// Complex nested config with block scalars\nconst appConfig = `---\n# Application Configuration\n# Environment: production\n\napp:\n  name: \"My Application\"\n  version: \"3.0.0-beta.1\"\n  description: >\n    A comprehensive web application\n    that handles user authentication,\n    data processing, and reporting.\n  license: |\n    MIT License\n\n    Copyright (c) 2026 Example Corp\n\n    Permission is hereby granted, free of charge,\n    to any person obtaining a copy of this software.\n\ndatabase:\n  primary:\n    host: db-primary.internal\n    port: 5432\n    name: app_production\n    pool:\n      min: 5\n      max: 20\n      idle_timeout: 30000\n  replicas:\n    - host: db-replica-1.internal\n      port: 5432\n      weight: 50\n    - host: db-replica-2.internal\n      port: 5432\n      weight: 50\n\nlogging:\n  level: info\n  format: json\n  outputs:\n    - type: stdout\n    - type: file\n      path: /var/log/app/app.log\n      rotation:\n        max_size: \"100MB\"\n        max_files: 10\n        compress: true\n\nfeatures:\n  flags: {dark_mode: true, beta_api: false, new_dashboard: true}\n  experiments:\n    - name: checkout_flow_v2\n      enabled: true\n      percentage: 25\n      groups: [beta_users, internal]\n...\n`;\n\nconst tests = [\n  { name: \"Kubernetes Deployment Manifest\", input: k8sManifest },\n  { name: \"GitHub Actions CI Config\", input: ciConfig },\n  { name: \"Docker Compose Config\", input: dockerCompose },\n  { name: \"Complex Application Config\", input: appConfig },\n];\n\nlet passed = 0;\nlet failed = 0;\n\nconsole.log(\"=== REALISTIC YAML FILE TESTS ===\\n\");\n\nfor (const t of tests) {\n  const result = validateYaml(t.input);\n  if (result.valid) {\n    passed++;\n    console.log(`  PASS: ${t.name} (${t.input.split(\"\\n\").length} lines)`);\n  } else {\n    failed++;\n    const err = result as { valid: false; line: number; message: string };\n    console.log(\n      `  FAIL: ${t.name} -- FALSE POSITIVE at line ${err.line}: \"${err.message}\"`\n    );\n    // Show the offending line for debugging\n    const lines = t.input.split(\"\\n\");\n    if (err.line >= 1 && err.line <= lines.length) {\n      console.log(`    Line ${err.line}: \"${lines[err.line - 1]}\"`);\n    }\n  }\n}\n\nconsole.log(`\\n=== SUMMARY ===`);\nconsole.log(`Total: ${tests.length} | Passed: ${passed} | Failed: ${failed}`);\nconsole.log(`\\n=== RESULT: ${failed === 0 ? \"ALL PASSED\" : \"FALSE POSITIVES DETECTED\"} ===`);\n"
