        "new_string": "import { validateYaml } from \"./yaml-validator\";\n\nexport async function runValidateCommand(args: string[]): Promise<void> {\n  const filePath = args[3];\n  if (!filePath) {\n    console.error(\"Usage: validate <file>\");\n    process.exit(1);\n  }\n\n  let content: string;\n  try {\n    const file = Bun.file(filePath);\n    if (!(await file.exists())) {\n      console.error(`Error: File not found: ${filePath}`);\n      process.exit(1);\n    }\n    content = await file.text();\n  } catch {\n    console.error(`Error: Cannot read file: ${filePath}`);\n    process.exit(1);\n    return;\n  }\n\n  const result = validateYaml(content);\n\n  if (result.valid) {\n    console.log(`${filePath}: valid YAML`);\n    process.exit(0);\n  } else {\n    console.error(`${filePath}:${result.line}: ${result.message}`);\n    process.exit(1);\n  }\n}"
