        "file_path": "/private/tmp/rp1-evals/a351e089/workspace/src/yaml-validator.test.ts",
        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateYaml } from \"./yaml-validator\";\nimport type { YamlValidationResult } from \"./yaml-validator\";\n\ndescribe(\"yaml-validator\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"empty string\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"simple key-value pair\", () => {\n      const result = validateYaml(\"name: Alice\\n\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multiple key-value pairs\", () => {\n      const result = validateYaml(\"name: Alice\\nage: 30\\ncity: Wonderland\\n\");\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"nested mappings\", () => {\n      const yaml = [\n        \"server:\",\n        \"  host: localhost\",\n        \"  port: 8080\",\n        \"  database:\",\n        \"    name: mydb\",\n        \"    user: admin\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"lists/sequences\", () => {\n      const yaml = [\n        \"fruits:\",\n        \"  - apple\",\n        \"  - banana\",\n        \"  - cherry\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"inline list\", () => {\n      const yaml = \"colors: [red, green, blue]\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"comments\", () => {\n      const yaml = [\n        \"# This is a comment\",\n        \"name: Alice # inline comment\",\n        \"  # indented comment\",\n        \"age: 30\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"block scalar with pipe (literal)\", () => {\n      const yaml = [\n        \"description: |\",\n        \"  This is a multi-line\",\n        \"  string that preserves newlines.\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"block scalar with greater-than (folded)\", () => {\n      const yaml = [\n        \"description: >\",\n        \"  This is a multi-line\",\n        \"  string that folds newlines.\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"block scalar with chomp modifier\", () => {\n      const yaml = [\n        \"text: |-\",\n        \"  stripped trailing newline\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"block scalar with keep modifier\", () => {\n      const yaml = [\n        \"text: |+\",\n        \"  keep trailing newlines\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"block scalar with indent indicator\", () => {\n      const yaml = [\n        \"text: |2\",\n        \"  two-space indented content\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"document start marker\", () => {\n      const yaml = [\n        \"---\",\n        \"name: Alice\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"document end marker\", () => {\n      const yaml = [\n        \"name: Alice\",\n        \"...\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multiple documents with markers\", () => {\n      const yaml = [\n        \"---\",\n        \"name: Alice\",\n        \"...\",\n        \"---\",\n        \"name: Bob\",\n        \"...\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"mixed content with mappings and sequences\", () => {\n      const yaml = [\n        \"users:\",\n        \"  - name: Alice\",\n        \"    age: 30\",\n        \"  - name: Bob\",\n        \"    age: 25\",\n        \"settings:\",\n        \"  debug: true\",\n        \"  verbose: false\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"double-quoted strings\", () => {\n      const yaml = 'message: \"Hello, World!\"\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"single-quoted strings\", () => {\n      const yaml = \"message: 'Hello, World!'\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"quoted key\", () => {\n      const yaml = '\"special key\": value\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"quoted key and quoted value\", () => {\n      const yaml = '\"key\": \"value\"\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"flow mapping\", () => {\n      const yaml = \"person: {name: Alice, age: 30}\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"flow sequence\", () => {\n      const yaml = \"colors: [red, green, blue]\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"nested flow collections\", () => {\n      const yaml = \"data: {items: [1, 2, 3], name: test}\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"boolean values\", () => {\n      const yaml = [\n        \"enabled: true\",\n        \"disabled: false\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"null values\", () => {\n      const yaml = [\n        \"value: null\",\n        \"other: ~\",\n        \"empty:\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"numeric values\", () => {\n      const yaml = [\n        \"integer: 42\",\n        \"float: 3.14\",\n        \"negative: -7\",\n        \"hex: 0xFF\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multi-line flow collection\", () => {\n      const yaml = [\n        \"items: [\",\n        \"  one,\",\n        \"  two,\",\n        \"  three\",\n        \"]\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"multi-line flow mapping\", () => {\n      const yaml = [\n        \"data: {\",\n        \"  name: Alice,\",\n        \"  age: 30\",\n        \"}\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"sequence of sequences\", () => {\n      const yaml = [\n        \"matrix:\",\n        \"  - - 1\",\n        \"    - 2\",\n        \"  - - 3\",\n        \"    - 4\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"escaped characters in double-quoted strings\", () => {\n      const yaml = 'message: \"line1\\\\nline2\\\\ttab\"\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"single quote with escaped single quote inside\", () => {\n      const yaml = \"message: 'it''s a test'\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n    });\n  });\n\n  describe(\"invalid YAML\", () => {\n    test(\"tab indentation reports correct line\", () => {\n      const yaml = [\n        \"name: Alice\",\n        \"\\tage: 30\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(2);\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"Tab\");\n      }\n    });\n\n    test(\"tab indentation on first line\", () => {\n      const yaml = \"\\tname: value\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(1);\n        expect(result.message).toContain(\"Tab\");\n      }\n    });\n\n    test(\"unclosed double quote reports correct line\", () => {\n      const yaml = [\n        \"name: Alice\",\n        'message: \"unclosed string',\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(2);\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"Unclosed\");\n      }\n    });\n\n    test(\"unclosed single quote reports correct line\", () => {\n      const yaml = [\n        \"name: Alice\",\n        \"message: 'unclosed string\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(2);\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"Unclosed\");\n      }\n    });\n\n    test(\"unclosed quote at start of line\", () => {\n      const yaml = '\"unclosed key\\n';\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(1);\n        expect(result.message).toContain(\"Unclosed\");\n      }\n    });\n\n    test(\"unclosed quote in list item\", () => {\n      const yaml = [\n        \"items:\",\n        '  - \"unclosed item',\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(2);\n        expect(result.message).toContain(\"Unclosed\");\n      }\n    });\n\n    test(\"unbalanced opening brace reports at end of file\", () => {\n      const yaml = \"data: {name: Alice\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"{\");\n      }\n    });\n\n    test(\"unbalanced closing brace reports correct line\", () => {\n      const yaml = [\n        \"name: Alice\",\n        \"}\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(2);\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"}\");\n      }\n    });\n\n    test(\"unbalanced opening bracket reports at end of file\", () => {\n      const yaml = \"items: [one, two\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"[\");\n      }\n    });\n\n    test(\"unbalanced closing bracket reports correct line\", () => {\n      const yaml = [\n        \"name: Alice\",\n        \"]\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(2);\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"]\");\n      }\n    });\n\n    test(\"invalid block scalar header with bad modifier\", () => {\n      const yaml = [\n        \"text: |invalid\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(1);\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"block scalar\");\n      }\n    });\n\n    test(\"invalid folded block scalar header\", () => {\n      const yaml = \"text: >bad\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(1);\n        expect(result.message).toContain(\"block scalar\");\n      }\n    });\n\n    test(\"bad indentation - dedent to never-established level\", () => {\n      const yaml = [\n        \"root:\",\n        \"    deep: value\",\n        \"  invalid: dedent\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(3);\n        expect(result.message.length).toBeGreaterThan(0);\n        expect(result.message).toContain(\"indentation\");\n      }\n    });\n\n    test(\"bad indentation with multiple levels\", () => {\n      const yaml = [\n        \"a:\",\n        \"  b:\",\n        \"      c: value\",\n        \"   d: bad\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(4);\n        expect(result.message).toContain(\"indentation\");\n      }\n    });\n\n    test(\"tab indentation detected before other checks\", () => {\n      const yaml = \"\\t{unbalanced\\n\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.line).toBe(1);\n        expect(result.message).toContain(\"Tab\");\n      }\n    });\n\n    test(\"first error wins - early exit\", () => {\n      const yaml = [\n        \"\\tbad tab\",\n        '\"unclosed quote',\n        \"}unmatched\",\n      ].join(\"\\n\");