        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { join } from \"path\";\nimport { mkdtemp, rm } from \"fs/promises\";\nimport { tmpdir } from \"os\";\n\nconst ENTRY_POINT = join(import.meta.dir, \"index.ts\");\nlet tempDir: string;\n\nasync function runCli(\n  ...args: string[]\n): Promise<{ stdout: string; stderr: string; exitCode: number }> {\n  const proc = Bun.spawn([\"bun\", \"run\", ENTRY_POINT, ...args], {\n    stdout: \"pipe\",\n    stderr: \"pipe\",\n  });\n  const [stdout, stderr] = await Promise.all([\n    new Response(proc.stdout).text(),\n    new Response(proc.stderr).text(),\n  ]);\n  const exitCode = await proc.exited;\n  return { stdout, stderr, exitCode };\n}\n\nbeforeAll(async () => {\n  tempDir = await mkdtemp(join(tmpdir(), \"yaml-validate-test-\"));\n});\n\nafterAll(async () => {\n  await rm(tempDir, { recursive: true, force: true });\n});\n\ndescribe(\"validate-command\", () => {\n  test(\"missing file argument produces usage message on stderr and exit code 1\", async () => {\n    const { stdout, stderr, exitCode } = await runCli(\"validate\");\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(\"Usage: validate <file>\");\n    expect(stdout).toBe(\"\");\n  });\n\n  test(\"non-existent file produces error message on stderr and exit code 1\", async () => {\n    const fakePath = join(tempDir, \"does-not-exist.yaml\");\n    const { stdout, stderr, exitCode } = await runCli(\"validate\", fakePath);\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(\"Error: File not found:\");\n    expect(stderr).toContain(fakePath);\n    expect(stdout).toBe(\"\");\n  });\n\n  test(\"valid YAML file produces success message on stdout and exit code 0\", async () => {\n    const filePath = join(tempDir, \"valid.yaml\");\n    await Bun.write(filePath, \"name: Alice\\nage: 30\\n\");\n\n    const { stdout, stderr, exitCode } = await runCli(\"validate\", filePath);\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(filePath);\n    expect(stdout).toContain(\"valid YAML\");\n  });\n\n  test(\"invalid YAML file produces error with line number on stderr and exit code 1\", async () => {\n    const filePath = join(tempDir, \"invalid.yaml\");\n    await Bun.write(filePath, \"name: Alice\\n\\tage: 30\\n\");\n\n    const { stdout, stderr, exitCode } = await runCli(\"validate\", filePath);\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(filePath);\n    expect(stderr).toMatch(/:\\d+:/);\n    expect(stderr.length).toBeGreaterThan(0);\n  });\n\n  test(\"empty file produces success result and exit code 0\", async () => {\n    const filePath = join(tempDir, \"empty.yaml\");\n    await Bun.write(filePath, \"\");\n\n    const { stdout, stderr, exitCode } = await runCli(\"validate\", filePath);\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(filePath);\n    expect(stdout).toContain(\"valid YAML\");\n  });\n\n  test(\"existing greeting behavior preserved when first argument is not validate\", async () => {\n    const { stdout, exitCode } = await runCli(\"Alice\");\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(\"Hello, Alice!\");\n  });\n});\n"
