/**
 * Prototype from-scratch YAML syntax checker.
 * DISPOSABLE - for hypothesis validation only.
 *
 * Design principles (from design.md):
 * 1. Conservative bias: accept when uncertain
 * 2. Line-number accuracy (1-indexed)
 * 3. Early exit: return first error
 * 4. State tracking: indentation stack, block scalar mode, flow collection depth
 * 5. Comment handling: skip comment lines, strip inline comments
 */

interface YamlValidationSuccess {
  valid: true;
}

interface YamlValidationError {
  valid: false;
  line: number;
  message: string;
}

type YamlValidationResult = YamlValidationSuccess | YamlValidationError;

export function validateYaml(content: string): YamlValidationResult {
  // Empty content is valid YAML
  if (content.trim() === "") {
    return { valid: true };
  }

  const lines = content.split("\n");

  // State tracking
  let flowDepthBraces = 0; // { } nesting
  let flowDepthBrackets = 0; // [ ] nesting
  let inBlockScalar = false;
  let blockScalarIndent = -1;
  let blockScalarStartLine = -1;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const rawLine = lines[i];

    // Check for tab indentation (YAML forbids tabs for indentation)
    if (/^\t/.test(rawLine) || /^ +\t/.test(rawLine)) {
      // Tab at start or mixed spaces then tab at start
      const tabMatch = rawLine.match(/^[ ]*\t/);
      if (tabMatch) {
        return {
          valid: false,
          line: lineNum,
          message: "Tab character used for indentation (YAML requires spaces)",
        };
      }
    }

    // Handle block scalar continuation
    if (inBlockScalar) {
      // Calculate current line indentation
      const currentIndent = rawLine.match(/^( *)/)?.[1]?.length ?? 0;
      const isEmptyOrWhitespace = rawLine.trim() === "";

      // Block scalar ends when we encounter a line with less or equal indentation
      // to the block scalar's parent (and it's not empty)
      if (!isEmptyOrWhitespace && currentIndent <= blockScalarIndent) {
        inBlockScalar = false;
        // Fall through to process this line normally
      } else {
        // Still in block scalar, skip normal processing
        continue;
      }
    }

    // Skip empty lines
    if (rawLine.trim() === "") {
      continue;
    }

    // Handle document markers
    if (rawLine.trim() === "---" || rawLine.trim() === "...") {
      continue;
    }

    // Strip comment-only lines
    if (/^\s*#/.test(rawLine)) {
      continue;
    }

    // Get the line content for further checks
    const line = rawLine;

    // Calculate indentation
    const indentMatch = line.match(/^( *)/);
    const indent = indentMatch ? indentMatch[1].length : 0;

    // Strip inline comments (but be careful about # inside quotes)
    const contentWithoutComment = stripInlineComment(line);

    // Check for block scalar headers: | or >
    const blockScalarMatch = contentWithoutComment.match(
      /:\s+([|>])([^\s]*)?\s*$/
    );
    const standaloneBlockScalar = contentWithoutComment.match(
      /^\s*([|>])([^\s]*)?\s*$/
    );

    if (blockScalarMatch || standaloneBlockScalar) {
      const match = blockScalarMatch || standaloneBlockScalar;
      const modifier = match![2] || "";

      // Validate block scalar header modifiers
      // Valid modifiers: optional [1-9] and/or [+-]
      if (modifier && !/^[1-9]?[+-]?$/.test(modifier) && !/^[+-]?[1-9]?$/.test(modifier)) {
        return {
          valid: false,
          line: lineNum,
          message: `Invalid block scalar header: "${match![1]}${modifier}"`,
        };
      }

      inBlockScalar = true;
      blockScalarIndent = indent;
      blockScalarStartLine = lineNum;
      continue;
    }

    // Check for unbalanced flow indicators on this line
    // We need to track quotes to avoid counting braces/brackets inside strings
    const flowResult = checkFlowIndicators(
      contentWithoutComment,
      lineNum,
      flowDepthBraces,
      flowDepthBrackets
    );
    if (!flowResult.valid) {
      return flowResult as YamlValidationError;
    }
    flowDepthBraces = flowResult.braces;
    flowDepthBrackets = flowResult.brackets;

    // Check for unclosed quotes (only when not in a flow collection context
    // and not a block scalar)
    const quoteResult = checkUnclosedQuotes(contentWithoutComment, lineNum);
    if (quoteResult) {
      return quoteResult;
    }
  }

  // After all lines: check if flow collections are balanced
  if (flowDepthBraces > 0) {
    return {
      valid: false,
      line: lines.length,
      message: "Unclosed flow mapping (unmatched '{')",
    };
  }
  if (flowDepthBrackets > 0) {
    return {
      valid: false,
      line: lines.length,
      message: "Unclosed flow sequence (unmatched '[')",
    };
  }

  return { valid: true };
}

/**
 * Strip inline comments while respecting quoted strings.
 */
function stripInlineComment(line: string): string {
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : "";

    if (ch === "'" && !inDoubleQuote) {
      // Check for escaped single quote in single-quoted string
      if (inSingleQuote && i + 1 < line.length && line[i + 1] === "'") {
        i++; // Skip escaped quote
        continue;
      }
      inSingleQuote = !inSingleQuote;
    } else if (ch === '"' && !inSingleQuote) {
      if (inDoubleQuote && prev === "\\") {
        continue; // Escaped double quote
      }
      inDoubleQuote = !inDoubleQuote;
    } else if (ch === "#" && !inSingleQuote && !inDoubleQuote) {
      // A comment starts with # preceded by a space (or at start of line)
      if (i === 0 || line[i - 1] === " ") {
        return line.substring(0, i).trimEnd();
      }
    }
  }

  return line;
}

/**
 * Check for unclosed quotes on a single line.
 * Returns an error if unclosed, or null if OK.
 */
function checkUnclosedQuotes(
  line: string,
  lineNum: number
): YamlValidationError | null {
  const trimmed = line.trim();

  // Skip lines that are part of flow collections or are just keys
  // We only care about values that start with a quote

  // Find the value portion after a key: or the whole line if it starts with a quote
  let valueStart = -1;

  // Check if line has a mapping key
  // Look for first unquoted colon followed by space or end of line
  let inSQ = false;
  let inDQ = false;
  for (let i = 0; i < trimmed.length; i++) {
    const ch = trimmed[i];
    if (ch === "'" && !inDQ) {
      if (inSQ && i + 1 < trimmed.length && trimmed[i + 1] === "'") {
        i++;
        continue;
      }
      inSQ = !inSQ;
    } else if (ch === '"' && !inSQ) {
      if (inDQ && i > 0 && trimmed[i - 1] === "\\") continue;
      inDQ = !inDQ;
    } else if (ch === ":" && !inSQ && !inDQ) {
      if (i + 1 >= trimmed.length || trimmed[i + 1] === " ") {
        valueStart = i + 1;
        break;
      }
    }
  }

  // Check the value part (or the whole line if it's a sequence item)
  let checkPart = trimmed;
  if (valueStart >= 0) {
    checkPart = trimmed.substring(valueStart).trim();
  } else if (trimmed.startsWith("- ")) {
    checkPart = trimmed.substring(2).trim();
  }

  if (checkPart.length === 0) return null;

  // Check if value starts with a quote
  if (checkPart[0] === '"') {
    if (!isQuotedStringClosed(checkPart, '"')) {
      return {
        valid: false,
        line: lineNum,
        message: 'Unclosed double quote',
      };
    }
  } else if (checkPart[0] === "'") {
    if (!isQuotedStringClosed(checkPart, "'")) {
      return {
        valid: false,
        line: lineNum,
        message: "Unclosed single quote",
      };
    }
  }

  return null;
}

/**
 * Check if a quoted string that starts with `quote` is properly closed.
 */
function isQuotedStringClosed(s: string, quote: '"' | "'"): boolean {
  // s starts with the opening quote
  for (let i = 1; i < s.length; i++) {
    if (s[i] === quote) {
      if (quote === '"' && s[i - 1] === "\\") {
        continue; // Escaped quote in double-quoted string
      }
      if (quote === "'" && i + 1 < s.length && s[i + 1] === "'") {
        i++; // Escaped quote in single-quoted string (two consecutive)
        continue;
      }
      // Found the closing quote
      return true;
    }
  }
  return false;
}

/**
 * Track flow indicators ({ } [ ]) on a line, respecting quotes.
 */
function checkFlowIndicators(
  line: string,
  lineNum: number,
  braces: number,
  brackets: number
): { valid: boolean; braces: number; brackets: number; line?: number; message?: string } {
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (ch === "'" && !inDoubleQuote) {
      if (inSingleQuote && i + 1 < line.length && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingleQuote = !inSingleQuote;
    } else if (ch === '"' && !inSingleQuote) {
      if (inDoubleQuote && i > 0 && line[i - 1] === "\\") continue;
      inDoubleQuote = !inDoubleQuote;
    } else if (!inSingleQuote && !inDoubleQuote) {
      if (ch === "{") braces++;
      else if (ch === "}") {
        braces--;
        if (braces < 0) {
          return {
            valid: false,
            braces,
            brackets,
            line: lineNum,
            message: "Unexpected '}' without matching '{'",
          };
        }
      } else if (ch === "[") brackets++;
      else if (ch === "]") {
        brackets--;
        if (brackets < 0) {
          return {
            valid: false,
            braces,
            brackets,
            line: lineNum,
            message: "Unexpected ']' without matching '['",
          };
        }
      }
    }
  }

  return { valid: true, braces, brackets };
}

