    input: "root:\n   \tchild: value\n",
    expectedValid: false,
    expectedLine: 2,
    description: "Three spaces then a tab -- still tab indentation",
  },
  {
    id: "E17",
    name: "Unclosed quote after nested content",
    input: `items:
  - name: "Alice
  - name: Bob
`,
    expectedValid: false,
    expectedLine: 2,
    description: "Unclosed double quote in sequence item value",
  },
  {
    id: "E18",
    name: "Invalid block scalar with letters",
    input: `data: |abc
  content here
`,
    expectedValid: false,
    expectedLine: 1,
    description: "Block scalar header with non-numeric, non-chomping characters",
  },
];

let totalTests = 0;
let passed = 0;
let failed = 0;
const failures: string[] = [];

function runTest(tc: TestCase) {
  totalTests++;
  const result = validateYaml(tc.input);

  if (tc.expectedValid) {
    if (result.valid) {
      passed++;
      console.log(`  PASS ${tc.id}: ${tc.name}`);
    } else {
      failed++;
      const err = result as { valid: false; line: number; message: string };
      const detail = `Expected VALID but got error at line ${err.line}: "${err.message}"`;
      failures.push(`${tc.id} (${tc.name}): ${detail}`);
      console.log(`  FAIL ${tc.id}: ${tc.name} -- ${detail}`);
    }
  } else {
    if (!result.valid) {
      const err = result as { valid: false; line: number; message: string };
      if (tc.expectedLine !== undefined && err.line !== tc.expectedLine) {
        failed++;
        const detail = `Error detected but wrong line: expected ${tc.expectedLine}, got ${err.line} ("${err.message}")`;
        failures.push(`${tc.id} (${tc.name}): ${detail}`);
        console.log(`  FAIL ${tc.id}: ${tc.name} -- ${detail}`);
      } else {
        passed++;
        console.log(
          `  PASS ${tc.id}: ${tc.name} -- error at line ${err.line}: "${err.message}"`
        );
      }
    } else {
      failed++;
      const detail = `Expected INVALID but got valid`;
      failures.push(`${tc.id} (${tc.name}): ${detail}`);
      console.log(`  FAIL ${tc.id}: ${tc.name} -- ${detail}`);
    }
  }
}

console.log("=== EDGE CASE TESTS ===");
console.log(`Testing ${edgeCases.length} edge cases:\n`);
for (const tc of edgeCases) {
  runTest(tc);
}

console.log("\n=== EDGE CASE SUMMARY ===");
console.log(`Total tests: ${totalTests}`);
console.log(`Passed: ${passed}`);
console.log(`Failed: ${failed}`);

if (failures.length > 0) {
  console.log("\n=== FAILURES ===");
  for (const f of failures) {
    console.log(`  - ${f}`);
  }
}

console.log(`\n=== RESULT: ${failed === 0 ? "ALL PASSED" : "SOME FAILED"} ===`);

