export async function runValidateCommand(args: string[]): Promise<void> {
  const filePath = args[3];
  if (!filePath) {
    console.error("Usage: validate <file>");
    process.exit(1);
  }
}

export interface YamlValidationSuccess {
  valid: true;
}

export interface YamlValidationError {
  valid: false;
  line: number;
  message: string;
}

export type YamlValidationResult = YamlValidationSuccess | YamlValidationError;

function stripInlineComment(line: string): string {
  let inSingle = false;
  let inDouble = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === "\\" && inDouble) {
      i++;
      continue;
    }
    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < line.length && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingle = !inSingle;
    } else if (
      ch === "#" &&
      !inSingle &&
      !inDouble &&
      i > 0 &&
      line[i - 1] === " "
    ) {
      return line.substring(0, i).trimEnd();
    }
  }
  return line;
}

function findQuotedStringEnd(text: string, startPos: number): number {
  const quoteChar = text[startPos];
  for (let i = startPos + 1; i < text.length; i++) {
    if (quoteChar === '"' && text[i] === "\\") {
      i++;
      continue;
    }
    if (text[i] === quoteChar) {
      if (quoteChar === "'" && i + 1 < text.length && text[i + 1] === "'") {
        i++;
        continue;
      }
      return i + 1;
    }
  }
  return -1;
}

function checkLineQuotes(trimmed: string): string | null {
  if (trimmed.length > 0 && (trimmed[0] === '"' || trimmed[0] === "'")) {
    const end = findQuotedStringEnd(trimmed, 0);
    if (end === -1) return "Unclosed quoted string";

    let pos = end;
    while (pos < trimmed.length && trimmed[pos] === " ") pos++;
    if (pos < trimmed.length && trimmed[pos] === ":") {
      pos++;
      while (pos < trimmed.length && trimmed[pos] === " ") pos++;
      if (
        pos < trimmed.length &&
        (trimmed[pos] === '"' || trimmed[pos] === "'")
      ) {
        const valEnd = findQuotedStringEnd(trimmed, pos);
        if (valEnd === -1) return "Unclosed quoted string";
      }
    }
    return null;
  }

  if (trimmed.startsWith("- ")) {
    let pos = 2;
    while (pos < trimmed.length && trimmed[pos] === " ") pos++;
    if (
      pos < trimmed.length &&
      (trimmed[pos] === '"' || trimmed[pos] === "'")
    ) {
      const end = findQuotedStringEnd(trimmed, pos);
      if (end === -1) return "Unclosed quoted string";
    }
    return null;
  }

  for (let i = 0; i < trimmed.length; i++) {
    if (
      trimmed[i] === ":" &&
      (i + 1 === trimmed.length || trimmed[i + 1] === " ")
    ) {
      let pos = i + 1;
      while (pos < trimmed.length && trimmed[pos] === " ") pos++;
      if (
        pos < trimmed.length &&
        (trimmed[pos] === '"' || trimmed[pos] === "'")
      ) {
        const end = findQuotedStringEnd(trimmed, pos);
        if (end === -1) return "Unclosed quoted string";
      }
      return null;
    }
  }

  return null;
}

function getValuePart(trimmed: string): string {
  if (trimmed.startsWith("- ")) {
    return trimmed.substring(2).trim();
  }

  let inSingle = false;
  let inDouble = false;
  for (let i = 0; i < trimmed.length; i++) {
    const ch = trimmed[i];
    if (ch === "\\" && inDouble) {
      i++;
      continue;
    }
    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < trimmed.length && trimmed[i + 1] === "'") {
        i++;
        continue;
      }
      inSingle = !inSingle;
    } else if (ch === ":" && !inSingle && !inDouble) {
      if (i + 1 === trimmed.length || trimmed[i + 1] === " ") {
        return i + 2 <= trimmed.length ? trimmed.substring(i + 2).trim() : "";
      }
    }
  }

  return trimmed;
}

function checkBlockScalarHeader(value: string): {
  isBlockScalar: boolean;
  error: string | null;
} {
  const trimVal = value.trim();
  if (trimVal.length === 0) return { isBlockScalar: false, error: null };

  const firstChar = trimVal[0];
  if (firstChar !== "|" && firstChar !== ">") {
    return { isBlockScalar: false, error: null };
  }

  const afterIndicator = trimVal.substring(1);
  if (/^([+-]?[1-9]?|[1-9][+-]?)\s*$/.test(afterIndicator)) {
    return { isBlockScalar: true, error: null };
  }

  const invalidPart = afterIndicator.trim();
  return {
    isBlockScalar: true,
    error: `Invalid block scalar header: invalid modifier '${invalidPart}' after '${firstChar}'`,
  };
}

function countFlowDeltas(
  line: string,
  currentBraces: number,
  currentBrackets: number
): { deltaBraces: number; deltaBrackets: number; error: string | null } {
  let deltaBraces = 0;
  let deltaBrackets = 0;
  let inSingle = false;
  let inDouble = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === "\\" && inDouble) {
      i++;
      continue;
    }
    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < line.length && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingle = !inSingle;
    } else if (!inSingle && !inDouble) {
      if (ch === "{") {
        deltaBraces++;
      } else if (ch === "}") {
        deltaBraces--;
        if (currentBraces + deltaBraces < 0) {
          return {
            deltaBraces,
            deltaBrackets,
            error: "Unexpected closing brace '}'",
          };
        }
      } else if (ch === "[") {
        deltaBrackets++;
      } else if (ch === "]") {
        deltaBrackets--;
        if (currentBrackets + deltaBrackets < 0) {
          return {
            deltaBraces,
            deltaBrackets,
            error: "Unexpected closing bracket ']'",
          };
        }
      }
    }
  }

  return { deltaBraces, deltaBrackets, error: null };
}

export function validateYaml(content: string): YamlValidationResult {
  if (content.length === 0 || content.trim().length === 0) {
    return { valid: true };
  }

  const lines = content.split("\n");

  let flowDepthBraces = 0;
  let flowDepthBrackets = 0;
  let inBlockScalar = false;
  let blockScalarIndent = 0;
  let indentStack: number[] = [0];

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const rawLine = lines[i];

    const leadingWs = rawLine.match(/^(\s*)/);
    if (leadingWs && leadingWs[1].includes("\t")) {
      return {
        valid: false,
        line: lineNum,
        message:
          "Tab character used for indentation (YAML forbids tabs for indentation)",
      };
    }

    const spaceMatch = rawLine.match(/^( *)/);
    const currentIndent = spaceMatch ? spaceMatch[1].length : 0;

    if (inBlockScalar) {
      if (rawLine.trim() === "") {
        continue;
      }
      if (currentIndent > blockScalarIndent) {
        continue;
      }
      inBlockScalar = false;
    }

    if (rawLine.trim() === "") continue;

    const trimmedRaw = rawLine.trim();
    if (trimmedRaw.startsWith("#")) continue;

    const stripped = stripInlineComment(rawLine);
    const trimmed = stripped.trim();
    if (trimmed === "") continue;

    if (trimmed === "---" || trimmed === "...") {
      indentStack = [0];
      inBlockScalar = false;
      continue;
    }

    const inFlow = flowDepthBraces > 0 || flowDepthBrackets > 0;

    if (!inFlow) {
      const value = getValuePart(trimmed);
      const bsCheck = checkBlockScalarHeader(value);
      if (bsCheck.error) {
        return { valid: false, line: lineNum, message: bsCheck.error };
      }
      if (bsCheck.isBlockScalar) {
        inBlockScalar = true;
        blockScalarIndent = currentIndent;
      }
    }

    const flowResult = countFlowDeltas(
      trimmed,
      flowDepthBraces,
      flowDepthBrackets
    );
    if (flowResult.error) {
      return { valid: false, line: lineNum, message: flowResult.error };
    }
    flowDepthBraces += flowResult.deltaBraces;
    flowDepthBrackets += flowResult.deltaBrackets;

    if (!inFlow && !inBlockScalar) {
      const quoteError = checkLineQuotes(trimmed);
      if (quoteError) {
        return { valid: false, line: lineNum, message: quoteError };
      }
    }

    if (!inFlow && !inBlockScalar) {
      if (currentIndent > indentStack[indentStack.length - 1]) {
        indentStack.push(currentIndent);
      } else if (currentIndent < indentStack[indentStack.length - 1]) {
        while (
          indentStack.length > 1 &&
          indentStack[indentStack.length - 1] > currentIndent
        ) {
          indentStack.pop();
        }
        if (indentStack[indentStack.length - 1] !== currentIndent) {
          return {
            valid: false,
            line: lineNum,
            message:
              "Invalid indentation: dedent to a level that was not previously established",
          };
        }
      }
    }
  }

  if (flowDepthBraces > 0) {
    return {
      valid: false,
      line: lines.length,
      message: "Unclosed flow mapping (unmatched '{')",
    };
  }
  if (flowDepthBrackets > 0) {
    return {
      valid: false,
      line: lines.length,
      message: "Unclosed flow sequence (unmatched '[')",
    };
  }

  return { valid: true };
}

