import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";
import type { YamlValidationResult } from "./yaml-validator";

describe("yaml-validator", () => {
  describe("valid YAML", () => {
    test("empty string", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
    });

    test("simple key-value pair", () => {
      const result = validateYaml("name: Alice\n");
      expect(result.valid).toBe(true);
    });

    test("multiple key-value pairs", () => {
      const result = validateYaml("name: Alice\nage: 30\ncity: Wonderland\n");
      expect(result.valid).toBe(true);
    });

    test("nested mappings", () => {
      const yaml = [
        "server:",
        "  host: localhost",
        "  port: 8080",
        "  database:",
        "    name: mydb",
        "    user: admin",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("lists/sequences", () => {
      const yaml = [
        "fruits:",
        "  - apple",
        "  - banana",
        "  - cherry",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("inline list", () => {
      const yaml = "colors: [red, green, blue]\n";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("comments", () => {
      const yaml = [
        "# This is a comment",
        "name: Alice # inline comment",
        "  # indented comment",
        "age: 30",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("block scalar with pipe (literal)", () => {
      const yaml = [
        "description: |",
        "  This is a multi-line",
        "  string that preserves newlines.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("block scalar with greater-than (folded)", () => {
      const yaml = [
        "description: >",
        "  This is a multi-line",
        "  string that folds newlines.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("block scalar with chomp modifier", () => {
      const yaml = [
        "text: |-",
        "  stripped trailing newline",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("block scalar with keep modifier", () => {
