        "content": "// HYP-002 Final: Exhaustive check of error message content and all error properties\n// Goal: Determine if ANY YAML-source position info is available anywhere\n\nconsole.log(\"=== HYP-002 Final Verification ===\\n\");\n\n// Use eval to call from different source positions to prove line/col are JS source positions\nconst testCases = [\n  \"[unclosed\",\n  \"a:\\n  - b\\n  c: [bad\",\n  \"a: {\\nb: c\",\n  \"---\\na: 1\\n---\\nb: [invalid\",\n  \"a: 1\\nb: 2\\nc: 3\\nd: 4\\ne: 5\\nf: 6\\ng: 7\\nh: 8\\ni: 9\\nj: 10\\nk: [bad\",\n];\n\nfor (const yaml of testCases) {\n  try {\n    Bun.YAML.parse(yaml);\n    console.log(`Input ${JSON.stringify(yaml).slice(0, 40)}: Parsed OK`);\n  } catch (e: any) {\n    const msgHasPosition = /line|col|pos|offset|row|char/i.test(e.message);\n    console.log(`Input: ${JSON.stringify(yaml).slice(0, 50)}`);\n    console.log(`  message: \"${e.message}\"`);\n    console.log(`  message has position info: ${msgHasPosition}`);\n    console.log(`  line (JS source): ${e.line}`);\n    console.log(`  column (JS source): ${e.column}`);\n\n    // Check every property on the error for anything YAML-specific\n    const descriptors = Object.getOwnPropertyDescriptors(e);\n    for (const [key, desc] of Object.entries(descriptors)) {\n      if (![\"message\", \"stack\", \"line\", \"column\", \"originalLine\", \"originalColumn\", \"sourceURL\"].includes(key)) {\n        console.log(`  EXTRA PROP e.${key} = ${desc.value}`);\n      }\n    }\n    console.log(\"\");\n  }\n}\n\n// Also verify: call Bun.YAML.parse from a different line to prove line/column changes\nconsole.log(\"\\n--- Line position proof ---\");\ntry { Bun.YAML.parse(\"[bad\"); } catch (e: any) { console.log(\"Call at ~line 38: e.line =\", e.line); }\n\n\n\n\ntry { Bun.YAML.parse(\"[bad\"); } catch (e: any) { console.log(\"Call at ~line 43: e.line =\", e.line); }\n\nconsole.log(\"\\n=== HYP-002 Final Complete ===\");\n"
