        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateYaml } from \"./yaml-validator\";\n\ndescribe(\"validateYaml\", () => {\n  test(\"valid simple YAML returns valid result\", () => {\n    const result = validateYaml(\"key: value\");\n    expect(result.valid).toBe(true);\n    expect(result.error).toBeUndefined();\n  });\n\n  test(\"valid multi-line YAML returns valid result\", () => {\n    const result = validateYaml(\n      \"name: project\\nversion: 1.0\\nitems:\\n  - one\\n  - two\"\n    );\n    expect(result.valid).toBe(true);\n    expect(result.error).toBeUndefined();\n  });\n\n  test(\"invalid YAML returns invalid result with error message\", () => {\n    const result = validateYaml(\"key: [invalid\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n    expect(result.error!.message).toBeString();\n    expect(result.error!.message.length).toBeGreaterThan(0);\n  });\n\n  test(\"invalid YAML error has undefined line and column\", () => {\n    const result = validateYaml(\"key: [invalid\");\n    expect(result.valid).toBe(false);\n    expect(result.error).toBeDefined();\n    expect(result.error!.line).toBeUndefined();\n    expect(result.error!.column).toBeUndefined();\n  });\n\n  test(\"empty string is valid YAML\", () => {\n    const result = validateYaml(\"\");\n    expect(result.valid).toBe(true);\n    expect(result.error).toBeUndefined();\n  });\n});\n"
