/** Result of a YAML validation attempt. */
export interface YamlValidationResult {
  valid: boolean;
  error?: {
    message: string;
    line?: number;
    column?: number;
  };
}

/**
 * Validate a string as syntactically correct YAML.
 * Returns a result object indicating success or failure with error details.
 */
export function validateYaml(content: string): YamlValidationResult {
  try {
    Bun.YAML.parse(content);
    return { valid: true };
  } catch (e: unknown) {
    const message =
      e instanceof Error ? e.message : "Unknown YAML parse error";
    return {
      valid: false,
      error: { message },
    };
  }
}

