// HYP-002: Test if Bun.YAML.parse provides line/column in errors
console.log("=== HYP-002: Error Position Information ===");

const invalidYamls = [
  {
    name: "Unclosed flow sequence",
    content: `key: [value1, value2\nother: stuff`,
  },
  {
    name: "Bad indentation",
    content: `parent:\n  child1: a\n child2: b`,
  },
  {
    name: "Duplicate key",
    content: `key: value1\nkey: value2`,
  },
  {
    name: "Tab character in indentation",
    content: `parent:\n\tchild: value`,
  },
  {
    name: "Invalid mapping",
    content: `key: value\n  unexpected: indentation`,
  },
  {
    name: "Truncated flow mapping",
    content: `{key: value`,
  },
  {
    name: "Colon in flow context",
    content: `{key: val:ue}`,
  },
  {
    name: "Missing colon",
    content: `key value\nkey2: value2`,
  },
];

for (const test of invalidYamls) {
  console.log(`\n--- Test: ${test.name} ---`);
  console.log(`Input: ${JSON.stringify(test.content)}`);
  try {
    const result = (Bun as any).YAML.parse(test.content);
    console.log("PARSED (no error thrown):", JSON.stringify(result));
  } catch (e: any) {
    console.log("Error thrown!");
    console.log("  e.message:", e.message);
    console.log("  e.name:", e.name);
    console.log("  e.constructor.name:", e.constructor?.name);

    // Check for line/column properties
    console.log("  e.line:", e.line);
    console.log("  e.column:", e.column);
    console.log("  e.position:", e.position);
    console.log("  e.offset:", e.offset);
    console.log("  e.mark:", e.mark);

    // Check all enumerable properties
    const props = Object.getOwnPropertyNames(e);
    console.log("  All own properties:", props);

    // Check if message contains line/column info
    const hasLineInMsg = /line\s*\d+/i.test(e.message);
    const hasColInMsg = /col(umn)?\s*\d+/i.test(e.message);
    console.log("  Message contains line ref:", hasLineInMsg);
    console.log("  Message contains column ref:", hasColInMsg);

    // Print full error for inspection
    console.log("  Full error string:", String(e));
  }
}

console.log("\n=== HYP-002 Complete ===");
